/**
 * Thicken thin English chapters (ch26–ch34) with curated pedagogical packs.
 * Run: node scripts/thicken-english-thin-chapters.mjs
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { mc, fb, tr, ec, sb, pack } from "./exercise-pack-utils.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PACKS_PATH = path.join(
  __dirname,
  "../src/config/exercise-banks/data/english-packs.json",
);

const TYPES = [
  "multiple_choice",
  "fill_blank",
  "translation",
  "error_correction",
  "sentence_building",
];

const PER_TYPE = 20;

function mergeType(existing = [], incoming = []) {
  const seen = new Set();
  const out = [];
  for (const item of [...existing, ...incoming]) {
    if (!item?.question?.trim()) continue;
    const key = `${item.type}|${item.question.trim().toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
    if (out.length >= PER_TYPE) break;
  }
  return out;
}

function mergeChapter(existing = {}, generated) {
  const out = { ...existing };
  for (const type of TYPES) {
    out[type] = mergeType(existing[type] ?? [], generated[type] ?? []);
  }
  return out;
}

function counts(ch = {}) {
  return Object.fromEntries(TYPES.map((t) => [t, (ch[t] ?? []).length]));
}

