const GENERATORS = {
  "eng-ch26-articles": pack26,
  "eng-ch27-possessives": pack27,
  "eng-ch28-countable": pack28,
  "eng-ch29-pp-intro": pack29,
  "eng-ch30-conditionals-review": pack30,
  "eng-ch31-reported-speech": pack31,
  "eng-ch32-relative-clauses": pack32,
  "eng-ch33-passive-advanced": pack33,
  "eng-ch34-modals-deduction": pack34,
};

function main() {
  const packs = JSON.parse(fs.readFileSync(PACKS_PATH, "utf8"));

  for (const [slug, gen] of Object.entries(GENERATORS)) {
    const before = counts(packs[slug]);
    const generated = gen();
    packs[slug] = mergeChapter(packs[slug] ?? {}, generated);
    const after = counts(packs[slug]);
    console.log(`\n${slug}`);
    for (const t of TYPES) {
      console.log(`  ${t}: ${before[t]} → ${after[t]}`);
    }
  }

  fs.writeFileSync(PACKS_PATH, `${JSON.stringify(packs, null, 2)}\n`, "utf8");
  console.log(`\nWrote ${PACKS_PATH}`);
}

main();
